use std::collections::VecDeque;struct PhoneDirectory{q:VecDeque<i32>,used:Vec<bool>}impl PhoneDirectory{fn new(n:i32)->Self{Self{q:(0..n).collect(),used:vec![false;n as usize]}}fn get(&mut self)->i32{if let Some(x)=self.q.pop_front(){self.used[x as usize]=true;x}else{-1}}fn check(&self,n:i32)->bool{n>=0&&(n as usize)<self.used.len()&&!self.used[n as usize]}fn release(&mut self,n:i32){if n>=0&&(n as usize)<self.used.len()&&self.used[n as usize]{self.used[n as usize]=false;self.q.push_back(n)}}}
